/// Run the complete Rust-native acoustic diarization pipeline over canonical
/// 16 kHz mono PCM.
pub fn diarize_acoustic_pcm<C>(
    input: AcousticDiarizationInput<'_>,
    is_cancelled: C,
) -> FwResult<(DiarizationReport, DiarizationProjection)>
where
    C: FnMut() -> bool,
{
    diarize_acoustic_pcm_with_ablation(input, AcousticFeatureAblation::FullV2, is_cancelled)
}

/// Run the native acoustic pipeline while preserving structured checkpoint
/// failures such as stage deadlines.
///
/// The shared acoustic implementation still accepts a boolean cancellation
/// poll for its inner loops. This adapter records the first structured error
/// and restores it when the inner pipeline returns its generic cancellation
/// sentinel.
pub fn diarize_acoustic_pcm_with_checkpoint(
    input: AcousticDiarizationInput<'_>,
    checkpoint: &(dyn Fn() -> FwResult<()> + Sync),
) -> FwResult<(DiarizationReport, DiarizationProjection)> {
    let cancellation = CheckpointCancellationAdapter::new(checkpoint);
    let outcome = diarize_acoustic_pcm(input, || cancellation.is_cancelled());
    cancellation.restore(outcome)
}

/// Run one frozen representation ablation through the otherwise identical
/// native acoustic pipeline.
///
/// This production-facing convenience path deliberately retains the
/// fixed-safe change detector while posterior candidates are fail-closed by
/// their public evidence gates.
pub fn diarize_acoustic_pcm_with_ablation<C>(
    input: AcousticDiarizationInput<'_>,
    feature_ablation: AcousticFeatureAblation,
    is_cancelled: C,
) -> FwResult<(DiarizationReport, DiarizationProjection)>
where
    C: FnMut() -> bool,
{
    diarize_acoustic_pcm_with_ablation_and_detector(
        input,
        feature_ablation,
        AcousticChangeDetectorMode::FixedSafeV1,
        is_cancelled,
    )
}

/// Run one frozen representation and change-detector ablation through the
/// otherwise identical native acoustic pipeline.
pub fn diarize_acoustic_pcm_with_ablation_and_detector<C>(
    input: AcousticDiarizationInput<'_>,
    feature_ablation: AcousticFeatureAblation,
    detector_mode: AcousticChangeDetectorMode,
    is_cancelled: C,
) -> FwResult<(DiarizationReport, DiarizationProjection)>
where
    C: FnMut() -> bool,
{
    let (report, projection, _, _, _) = diarize_acoustic_pcm_with_detector_evidence_internal(
        input,
        feature_ablation,
        detector_mode,
        AcousticClusteringMode::FixedSafeV1,
        None,
        false,
        SpeakerRepresentationProvider::AcousticV2,
        is_cancelled,
    )?;
    Ok((report, projection))
}

/// Run one explicit detector/clustering combination for aggregate evaluation.
pub(crate) fn diarize_acoustic_pcm_with_modes_evidence<C>(
    input: AcousticDiarizationInput<'_>,
    feature_ablation: AcousticFeatureAblation,
    detector_mode: AcousticChangeDetectorMode,
    clustering_mode: AcousticClusteringMode,
    is_cancelled: C,
) -> FwResult<(
    DiarizationReport,
    DiarizationProjection,
    AcousticChangeEvaluationEvidence,
    AcousticClusteringEvaluationEvidence,
)>
where
    C: FnMut() -> bool,
{
    let (report, projection, change_evidence, clustering_evidence, _) =
        diarize_acoustic_pcm_with_detector_evidence_internal(
            input,
            feature_ablation,
            detector_mode,
            clustering_mode,
            None,
            true,
            SpeakerRepresentationProvider::AcousticV2,
            is_cancelled,
        )?;
    Ok((report, projection, change_evidence, clustering_evidence))
}

/// Run the full-v2 acoustic pipeline with an optional, evaluation-only
/// sidecar fused into the existing boundary selector.
///
/// `None` takes the same default path as [`diarize_acoustic_pcm_with_modes_evidence`].
/// A request is configuration-bound, keeps its observations in the existing
/// 401-frame segmentation horizon, and never changes production defaults.
pub(crate) fn diarize_acoustic_pcm_with_sidecar_evidence<C>(
    input: AcousticDiarizationInput<'_>,
    detector_mode: AcousticChangeDetectorMode,
    clustering_mode: AcousticClusteringMode,
    sidecar_request: Option<AcousticSidecarEvaluationRequest>,
    is_cancelled: C,
) -> FwResult<(
    DiarizationReport,
    DiarizationProjection,
    AcousticChangeEvaluationEvidence,
    AcousticClusteringEvaluationEvidence,
    AcousticSidecarFusionEvaluationEvidence,
)>
where
    C: FnMut() -> bool,
{
    diarize_acoustic_pcm_with_detector_evidence_internal(
        input,
        AcousticFeatureAblation::FullV2,
        detector_mode,
        clustering_mode,
        sidecar_request,
        true,
        SpeakerRepresentationProvider::AcousticV2,
        is_cancelled,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "the evaluation harness passes independent algorithm ablation levers"
)]
fn diarize_acoustic_pcm_with_detector_evidence_internal<C>(
    input: AcousticDiarizationInput<'_>,
    feature_ablation: AcousticFeatureAblation,
    detector_mode: AcousticChangeDetectorMode,
    clustering_mode: AcousticClusteringMode,
    sidecar_request: Option<AcousticSidecarEvaluationRequest>,
    capture_evaluation_evidence: bool,
    representation_provider: SpeakerRepresentationProvider<'_>,
    mut is_cancelled: C,
) -> FwResult<(
    DiarizationReport,
    DiarizationProjection,
    AcousticChangeEvaluationEvidence,
    AcousticClusteringEvaluationEvidence,
    AcousticSidecarFusionEvaluationEvidence,
)>
where
    C: FnMut() -> bool,
{
    let AcousticDiarizationInput {
        samples,
        normalized_input_sha256,
        segments,
        word_aligned,
        request,
        boundary_hints,
    } = input;
    let engine_matches_provider = matches!(
        (request.engine, representation_provider),
        (
            DiarizationEngine::Auto | DiarizationEngine::Acoustic,
            SpeakerRepresentationProvider::AcousticV2
        ) | (
            DiarizationEngine::Ecapa,
            SpeakerRepresentationProvider::EcapaTdnnV1 {
                evidence_mode: DiarizationSpeakerEvidenceMode::EcapaOnly,
                ..
            }
        ) | (
            DiarizationEngine::EcapaFused,
            SpeakerRepresentationProvider::EcapaTdnnV1 {
                evidence_mode: DiarizationSpeakerEvidenceMode::EcapaWithAcousticChannel,
                ..
            }
        )
    );
    if !engine_matches_provider {
        return Err(FwError::InvalidRequest(format!(
            "native diarization representation does not match the requested {:?} engine",
            request.engine,
        )));
    }
    if normalized_input_sha256.len() != 64
        || !normalized_input_sha256
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(FwError::InvalidRequest(
            "normalized_input_sha256 must be exactly 64 lowercase hexadecimal characters"
                .to_owned(),
        ));
    }
    let audio_duration_ms = samples_to_ms(samples.len());
    request
        .validate(audio_duration_ms)
        .map_err(|error| FwError::InvalidRequest(error.to_string()))?;
    let supervised_boundaries_ms = supervised_enrollment_boundaries_ms(request);
    let mut segmenter = AcousticSegmenter::new_with_supervised_boundaries(
        boundary_hints,
        &supervised_boundaries_ms,
        feature_ablation,
        detector_mode,
    )?;
    segmenter.capture_evaluation_evidence = capture_evaluation_evidence;
    let mut sidecar_adapter = sidecar_request
        .map(|request| AcousticSidecarBoundaryAdapter::new(request, detector_mode))
        .transpose()?;
    if sidecar_adapter.is_some() {
        segmenter.enable_sidecar_fusion()?;
    }
    let _extraction = if let Some(adapter) = sidecar_adapter.as_mut() {
        extract_acoustic_features_with_frames(
            samples,
            &mut is_cancelled,
            |frame_samples, frame, is_cancelled| {
                let signal = adapter.observe(frame_samples, &frame, is_cancelled)?;
                segmenter.push_with_sidecar_signal(frame, signal)
            },
        )?
    } else {
        extract_acoustic_features(samples, &mut is_cancelled, |frame| segmenter.push(frame))?
    };
    if is_cancelled() {
        return Err(FwError::Cancelled(
            "acoustic diarization cancelled after feature extraction".to_owned(),
        ));
    }
    let (tracklets, _segmentation, change_evaluation_evidence, sidecar_selector) =
        segmenter.finish()?;
    let sidecar_evaluation = if let Some(adapter) = sidecar_adapter {
        adapter.finish(sidecar_selector)?
    } else {
        AcousticSidecarFusionEvaluationEvidence::default()
    };
    let (mut neural_representation, neural_embeddings, evidence_mode) =
        match representation_provider {
            SpeakerRepresentationProvider::AcousticV2 => (
                None,
                BTreeMap::new(),
                DiarizationSpeakerEvidenceMode::AcousticV2,
            ),
            SpeakerRepresentationProvider::EcapaTdnnV1 {
                model,
                checkpoint,
                evidence_mode,
            } => {
                let (summary, embeddings) =
                    apply_ecapa_speaker_representations(samples, &tracklets, model, checkpoint)?;
                (Some(summary), embeddings, evidence_mode)
            }
        };
    let enrollment_identity_authority = match representation_provider {
        SpeakerRepresentationProvider::AcousticV2 => EnrollmentIdentityAuthority::AcousticV2,
        SpeakerRepresentationProvider::EcapaTdnnV1 { .. } => {
            EnrollmentIdentityAuthority::Ecapa(&neural_embeddings)
        }
    };
    let mut enrollment = enroll_known_speaker_profiles_with_authority(
        &tracklets,
        request,
        audio_duration_ms,
        enrollment_identity_authority,
    )
    .map_err(|error| FwError::InvalidRequest(error.to_string()))?;
    if neural_representation.is_some() {
        let (quarantined, contradictory) =
            apply_neural_enrollment_hygiene(&tracklets, &mut enrollment, &neural_embeddings);
        if quarantined > 0
            && let Some(summary) = neural_representation.as_mut()
        {
            summary.status = NeuralSpeakerRepresentationStatus::Degraded;
            if contradictory
                && !summary
                    .reasons
                    .contains(&NeuralSpeakerRepresentationReason::ContradictoryEnrollment)
            {
                summary
                    .reasons
                    .push(NeuralSpeakerRepresentationReason::ContradictoryEnrollment);
            }
            summary.validate().map_err(FwError::ContractViolation)?;
        }
    }
    let (clustering, count_merge_steps) = cluster_acoustic_tracklets_with_budgeted_enrollment(
        &tracklets,
        &mut enrollment,
        &request.speaker_count,
        usize::from(request.max_prototypes),
        clustering_mode,
        neural_representation
            .is_some()
            .then_some(&neural_embeddings),
        evidence_mode,
        is_cancelled,
    )?;
    let neural_identity_unavailable = neural_representation
        .as_ref()
        .is_some_and(|summary| summary.status == NeuralSpeakerRepresentationStatus::Unavailable);
    // A loaded ECAPA model can legitimately yield zero embeddings for short or
    // non-identity-bearing speech. Preserve only immutable hard attribution in
    // that case; acoustic-only clusters are not evidence produced by the
    // requested ECAPA identity representation.
    let unavailable_assignments = neural_identity_unavailable.then(|| {
        tracklets
            .iter()
            .map(|tracklet| {
                enrollment
                    .hard_assignments
                    .get(&tracklet.tracklet_index)
                    .map_or_else(
                        || unknown_assignment(tracklet),
                        |speaker_ref| AcousticSpeakerAssignment {
                            tracklet_index: tracklet.tracklet_index,
                            start_ms: tracklet.start_ms,
                            end_ms: tracklet.end_ms,
                            speaker_ref: Some(speaker_ref.clone()),
                            speaker_confidence: 1.0,
                            secondary_speaker_ref: None,
                            secondary_speaker_confidence: None,
                            change_confidence: tracklet.change_confidence,
                            overlap_suspected: false,
                            hard_attribution: true,
                        },
                    )
            })
            .collect::<Vec<_>>()
    });
    let report_assignments = unavailable_assignments
        .as_deref()
        .unwrap_or(&clustering.assignments);
    let turns = diarization_turns_from_assignments(report_assignments, audio_duration_ms)?;
    let speaker_queries = if neural_identity_unavailable {
        Vec::new()
    } else {
        speaker_attribution_queries(report_assignments, normalized_input_sha256)
    };
    let projection = project_diarization_onto_segments(segments, &turns, word_aligned)?;
    let fallback_status = if neural_identity_unavailable {
        match request.speaker_count {
            SpeakerCountRequest::Infer
            | SpeakerCountRequest::Prior { .. }
            | SpeakerCountRequest::Range { .. } => {
                DiarizationFallbackStatus::SpeakerCountUnresolved
            }
            SpeakerCountRequest::HardConstraint { count } => {
                let attributed_count = report_assignments
                    .iter()
                    .filter_map(|assignment| {
                        assignment
                            .hard_attribution
                            .then_some(assignment.speaker_ref.as_deref())
                            .flatten()
                    })
                    .collect::<BTreeSet<_>>()
                    .len();
                if attributed_count == count as usize {
                    DiarizationFallbackStatus::InsufficientEvidence
                } else {
                    DiarizationFallbackStatus::UnsatisfiedConstraints
                }
            }
        }
    } else if matches!(
        request.speaker_count,
        SpeakerCountRequest::Infer
            | SpeakerCountRequest::Prior { .. }
            | SpeakerCountRequest::Range { .. }
    ) && clustering
        .count_estimate
        .as_ref()
        .and_then(|estimate| estimate.selected_count)
        .is_none()
    {
        DiarizationFallbackStatus::SpeakerCountUnresolved
    } else if !clustering.constraints_satisfied {
        DiarizationFallbackStatus::UnsatisfiedConstraints
    } else {
        DiarizationFallbackStatus::NotNeeded
    };
    if request.fallback == DiarizationFallbackPolicy::Error
        && fallback_status != DiarizationFallbackStatus::NotNeeded
    {
        return Err(FwError::InvalidRequest(format!(
            "native acoustic diarization fallback triggered: {fallback_status:?}"
        )));
    }
    let speaker_count = if neural_identity_unavailable {
        unavailable_neural_speaker_count_outcome(
            &request.speaker_count,
            &tracklets,
            report_assignments,
        )?
    } else {
        public_speaker_count_outcome(&request.speaker_count, &clustering)?
    };
    let mut hint_evidence = public_hint_evidence(&enrollment.evidence)?;
    if neural_identity_unavailable {
        normalize_unavailable_neural_hint_evidence(
            &mut hint_evidence,
            &request.known_intervals,
            report_assignments,
        )?;
    }
    // Public diagnostics are finite stable codes. Native acoustic metrics are
    // already represented by typed report and evaluation fields, so successful
    // native production contributes no diagnostic code here.
    let diagnostics = neural_identity_unavailable
        .then(|| crate::model::DIARIZATION_DIAGNOSTIC_NEURAL_IDENTITY_UNAVAILABLE.to_owned())
        .into_iter()
        .collect();
    let clustering_evaluation = AcousticClusteringEvaluationEvidence {
        requested_mode: clustering.requested_mode,
        executed_mode: clustering.executed_mode,
        fallback_reason: clustering.fallback_reason,
        speaker_count_stability: clustering.bootstrap_stability,
        count_estimate: capture_evaluation_evidence
            .then(|| clustering.count_estimate.clone())
            .flatten(),
        count_merge_steps: if capture_evaluation_evidence {
            count_merge_steps
        } else {
            Vec::new()
        },
        speaker_evidence: if capture_evaluation_evidence {
            clustering.speaker_evidence.clone()
        } else {
            Vec::new()
        },
        calibration_tracklets: if capture_evaluation_evidence {
            tracklets
        } else {
            Vec::new()
        },
    };
    let report = DiarizationReport {
        implementation: if neural_identity_unavailable {
            "native-ecapa-unavailable-v1".to_owned()
        } else if neural_representation.is_some() {
            match evidence_mode {
                DiarizationSpeakerEvidenceMode::EcapaOnly => "native-ecapa-only-v1",
                DiarizationSpeakerEvidenceMode::EcapaWithAcousticChannel => "native-ecapa-fused-v1",
                _ => "native-ecapa-invalid",
            }
            .to_owned()
        } else {
            match feature_ablation.schema_version() {
                AcousticFeatureSchemaVersion::V1 => "native-acoustic-v1",
                AcousticFeatureSchemaVersion::V2 => "native-acoustic-v2",
            }
            .to_owned()
        },
        contract_version: if neural_representation.is_some() {
            NEURAL_DIARIZATION_CONTRACT_VERSION.to_owned()
        } else {
            ACOUSTIC_DIARIZATION_CONTRACT_VERSION.to_owned()
        },
        // ECAPA replaces only the identity representation. The common
        // segmentation and channel features remain acoustic-v2 and model
        // provenance has its own typed field below.
        feature_schema: feature_ablation.schema_version().id().to_owned(),
        speaker_evidence_mode: if neural_identity_unavailable {
            DiarizationSpeakerEvidenceMode::None
        } else {
            evidence_mode
        },
        normalized_input_sha256: normalized_input_sha256.to_owned(),
        hint_document_sha256: enrollment.hint_document_sha256,
        turns,
        profiles: if neural_identity_unavailable {
            Vec::new()
        } else {
            clustering.profiles
        },
        hint_evidence,
        speaker_queries,
        speaker_count,
        fallback_status,
        operational_partition: if neural_identity_unavailable {
            None
        } else {
            clustering.operational_partition
        },
        neural_representation,
        diagnostics,
    };
    validate_native_diarization_report(
        &report,
        request,
        audio_duration_ms,
        neural_identity_unavailable,
    )?;
    Ok((
        report,
        projection,
        change_evaluation_evidence,
        clustering_evaluation,
        sidecar_evaluation,
    ))
}

fn validate_native_diarization_report(
    report: &DiarizationReport,
    request: &DiarizationRequest,
    audio_duration_ms: u64,
    neural_identity_unavailable: bool,
) -> FwResult<()> {
    let defer_request_binding_to_fallback_orchestrator = neural_identity_unavailable
        && matches!(
            request.fallback,
            DiarizationFallbackPolicy::Acoustic | DiarizationFallbackPolicy::External
        );
    if defer_request_binding_to_fallback_orchestrator {
        // This is an intermediate native-attempt result, not the final result
        // authorized by the caller's fallback policy. It must still satisfy the
        // complete generic report contract before the orchestrator consumes it.
        report.validate().map_err(FwError::ContractViolation)
    } else {
        report
            .validate_against_request(request, Some(audio_duration_ms))
            .map_err(FwError::ContractViolation)
    }
}

fn public_speaker_count_outcome(
    request: &SpeakerCountRequest,
    clustering: &AcousticClusteringResult,
) -> FwResult<SpeakerCountOutcome> {
    let supported_speaker_count = u32::try_from(clustering.detected_speakers).map_err(|_| {
        FwError::InvalidRequest("supported speaker count exceeds report schema".to_owned())
    })?;
    let mut active_speaker_refs = clustering
        .speaker_evidence
        .iter()
        .filter(|evidence| evidence.supported)
        .map(|evidence| evidence.speaker_ref.clone())
        .collect::<Vec<_>>();
    active_speaker_refs.sort();
    let speaker_evidence = clustering
        .speaker_evidence
        .iter()
        .map(|evidence| -> FwResult<_> {
            Ok(SpeakerEvidenceSummary {
                speaker_ref: evidence.speaker_ref.clone(),
                assigned_tracklet_count: report_count(
                    evidence.assigned_tracklet_count,
                    "assigned tracklet count",
                )?,
                independent_tracklet_count: report_count(
                    evidence.independent_tracklet_count,
                    "independent tracklet count",
                )?,
                recurrence_episode_count: report_count(
                    evidence.recurrence_episode_count,
                    "recurrence episode count",
                )?,
                voiced_frame_count: report_count(
                    evidence.voiced_frame_count,
                    "voiced frame count",
                )?,
                independent_voiced_frame_count: report_count(
                    evidence.independent_voiced_frame_count,
                    "independent voiced frame count",
                )?,
                voiced_duration_ms: evidence.voiced_duration_ms,
                mean_assignment_confidence: f64::from(evidence.mean_assignment_confidence),
                profile_reliability: f64::from(evidence.cluster_reliability),
                hard_anchored: evidence.hard_anchored,
                separated_from_supported_speakers: evidence.separated_from_supported_speakers,
                reasons: evidence.reasons.clone(),
                supported: evidence.supported,
            })
        })
        .collect::<FwResult<Vec<_>>>()?;
    let status = match request {
        SpeakerCountRequest::Infer
        | SpeakerCountRequest::Prior { .. }
        | SpeakerCountRequest::Range { .. }
            if clustering
                .count_estimate
                .as_ref()
                .and_then(|estimate| estimate.selected_count)
                .is_some()
                && supported_speaker_count > 0 =>
        {
            SpeakerCountOutcomeStatus::Resolved
        }
        SpeakerCountRequest::Infer
        | SpeakerCountRequest::Prior { .. }
        | SpeakerCountRequest::Range { .. } => SpeakerCountOutcomeStatus::Unresolved,
        SpeakerCountRequest::HardConstraint { count } if supported_speaker_count == *count => {
            SpeakerCountOutcomeStatus::Satisfied
        }
        SpeakerCountRequest::HardConstraint { .. } => SpeakerCountOutcomeStatus::Unsatisfied,
    };
    let mut reasons = Vec::new();
    match status {
        SpeakerCountOutcomeStatus::Resolved => {
            reasons.push(SpeakerCountOutcomeReason::EvidenceSupportedCount);
        }
        SpeakerCountOutcomeStatus::Satisfied => {
            reasons.push(SpeakerCountOutcomeReason::RequestedCountMatched);
        }
        SpeakerCountOutcomeStatus::Unsatisfied => {
            reasons.push(SpeakerCountOutcomeReason::RequestedCountMismatch);
        }
        SpeakerCountOutcomeStatus::Unresolved => {
            if supported_speaker_count == 0 {
                reasons.push(SpeakerCountOutcomeReason::NoSupportedSpeakers);
            } else if matches!(request, SpeakerCountRequest::Prior { .. })
                && clustering.count_estimate.is_none()
            {
                reasons.push(SpeakerCountOutcomeReason::SpeakerCountPriorFusionUnavailable);
            } else {
                reasons.push(SpeakerCountOutcomeReason::SpeakerCountEvidenceUnresolved);
            }
        }
    }
    if clustering.detected_speakers > 1
        && clustering.dominant_speaker_share > MAX_MULTI_SPEAKER_DOMINANT_SHARE
    {
        reasons.push(SpeakerCountOutcomeReason::DominantSpeakerShareExceeded);
    }
    if !clustering.speaker_separation_satisfied {
        reasons.push(SpeakerCountOutcomeReason::AmbiguousSpeakerSeparation);
    }
    Ok(SpeakerCountOutcome {
        request: request.clone(),
        estimate: clustering.count_estimate.clone(),
        status,
        supported_speaker_count,
        active_speaker_refs,
        dominant_speaker_share: f64::from(clustering.dominant_speaker_share),
        unknown_voiced_share: f64::from(clustering.unknown_voiced_share),
        reasons,
        speaker_evidence,
    })
}

fn unavailable_neural_speaker_count_outcome(
    request: &SpeakerCountRequest,
    tracklets: &[AcousticTracklet],
    assignments: &[AcousticSpeakerAssignment],
) -> FwResult<SpeakerCountOutcome> {
    if tracklets.len() != assignments.len() {
        return Err(FwError::ContractViolation(
            "unavailable ECAPA attribution lost acoustic tracklet correspondence".to_owned(),
        ));
    }
    let active_speaker_refs = assignments
        .iter()
        .filter(|assignment| assignment.hard_attribution)
        .filter_map(|assignment| assignment.speaker_ref.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let supported_speaker_count = u32::try_from(active_speaker_refs.len()).map_err(|_| {
        FwError::ContractViolation(
            "hard-attributed ECAPA fallback speaker count exceeds the report schema".to_owned(),
        )
    })?;
    let (dominant_speaker_share, unknown_voiced_share) =
        assignment_voiced_shares(tracklets, assignments)?;
    let speaker_evidence = active_speaker_refs
        .iter()
        .map(|speaker_ref| {
            let mut assigned_tracklet_count = 0usize;
            let mut voiced_frame_count = 0usize;
            let mut voiced_duration_ms = 0u64;
            for (tracklet, assignment) in tracklets.iter().zip(assignments) {
                if assignment.hard_attribution
                    && assignment.speaker_ref.as_ref() == Some(speaker_ref)
                {
                    assigned_tracklet_count = assigned_tracklet_count.saturating_add(1);
                    voiced_frame_count =
                        voiced_frame_count.saturating_add(tracklet.voiced_frame_count);
                    voiced_duration_ms = voiced_duration_ms
                        .saturating_add(tracklet.end_ms.saturating_sub(tracklet.start_ms));
                }
            }
            Ok(SpeakerEvidenceSummary {
                speaker_ref: speaker_ref.clone(),
                assigned_tracklet_count: report_count(
                    assigned_tracklet_count,
                    "hard-attributed tracklet count",
                )?,
                independent_tracklet_count: report_count(
                    assigned_tracklet_count,
                    "hard-attributed independent tracklet count",
                )?,
                recurrence_episode_count: u64::from(assigned_tracklet_count > 0),
                voiced_frame_count: report_count(
                    voiced_frame_count,
                    "hard-attributed voiced frame count",
                )?,
                independent_voiced_frame_count: report_count(
                    voiced_frame_count,
                    "hard-attributed independent voiced frame count",
                )?,
                voiced_duration_ms,
                mean_assignment_confidence: 1.0,
                profile_reliability: 0.0,
                hard_anchored: true,
                separated_from_supported_speakers: true,
                reasons: vec![SpeakerEvidenceReason::SupportedByHardHint],
                supported: true,
            })
        })
        .collect::<FwResult<Vec<_>>>()?;
    let status = match request {
        SpeakerCountRequest::HardConstraint { count } if *count == supported_speaker_count => {
            SpeakerCountOutcomeStatus::Satisfied
        }
        SpeakerCountRequest::HardConstraint { .. } => SpeakerCountOutcomeStatus::Unsatisfied,
        SpeakerCountRequest::Infer
        | SpeakerCountRequest::Prior { .. }
        | SpeakerCountRequest::Range { .. } => SpeakerCountOutcomeStatus::Unresolved,
    };
    let status_reason = match status {
        SpeakerCountOutcomeStatus::Satisfied => SpeakerCountOutcomeReason::RequestedCountMatched,
        SpeakerCountOutcomeStatus::Unsatisfied => SpeakerCountOutcomeReason::RequestedCountMismatch,
        SpeakerCountOutcomeStatus::Unresolved if supported_speaker_count == 0 => {
            SpeakerCountOutcomeReason::NoSupportedSpeakers
        }
        SpeakerCountOutcomeStatus::Unresolved
            if matches!(request, SpeakerCountRequest::Prior { .. }) =>
        {
            SpeakerCountOutcomeReason::SpeakerCountPriorFusionUnavailable
        }
        SpeakerCountOutcomeStatus::Unresolved | SpeakerCountOutcomeStatus::Resolved => {
            SpeakerCountOutcomeReason::SpeakerCountEvidenceUnresolved
        }
    };
    Ok(SpeakerCountOutcome {
        request: request.clone(),
        estimate: None,
        status,
        supported_speaker_count,
        active_speaker_refs,
        dominant_speaker_share: f64::from(dominant_speaker_share),
        unknown_voiced_share: f64::from(unknown_voiced_share),
        reasons: vec![status_reason],
        speaker_evidence,
    })
}

fn normalize_unavailable_neural_hint_evidence(
    evidence: &mut [SpeakerHintEvidenceSummary],
    hints: &[KnownSpeakerInterval],
    assignments: &[AcousticSpeakerAssignment],
) -> FwResult<()> {
    if evidence.len() != hints.len() {
        return Err(FwError::ContractViolation(
            "unavailable ECAPA hint evidence lost request correspondence".to_owned(),
        ));
    }
    for (evidence, hint) in evidence.iter_mut().zip(hints) {
        evidence.profile_accepted_tracklet_count = 0;
        evidence.profile_downweighted_tracklet_count = 0;
        evidence.profile_quarantined_tracklet_count = 0;
        evidence.contradiction_score = None;
        let hard_attributed = hint.policy == KnownSpeakerPolicy::HardMustLink
            && assignments.iter().any(|assignment| {
                assignment.hard_attribution
                    && assignment.speaker_ref.as_deref() == Some(hint.speaker_ref.as_str())
                    && assignment.start_ms < hint.end_ms
                    && hint.start_ms < assignment.end_ms
            });
        if hard_attributed {
            evidence.disposition = SpeakerHintDisposition::HardAttributed;
            evidence.accepted_tracklet_count = evidence.usable_tracklet_count;
            evidence.rejected_tracklet_count = 0;
        } else {
            evidence.disposition = SpeakerHintDisposition::NoUsableTracklets;
            evidence.usable_tracklet_count = 0;
            evidence.accepted_tracklet_count = 0;
            evidence.rejected_tracklet_count = 0;
            evidence.applied_weight = 0.0;
        }
    }
    Ok(())
}

fn public_hint_evidence(
    evidence: &[HintEnrollmentEvidence],
) -> FwResult<Vec<SpeakerHintEvidenceSummary>> {
    evidence
        .iter()
        .map(|hint| {
            let disposition = if hint.usable_tracklet_count == 0 {
                SpeakerHintDisposition::NoUsableTracklets
            } else if hint.policy == KnownSpeakerPolicy::HardMustLink {
                SpeakerHintDisposition::HardAttributed
            } else if hint.accepted_tracklet_count == 0 {
                SpeakerHintDisposition::Rejected
            } else if hint.accepted_tracklet_count < hint.usable_tracklet_count
                || hint.rejected_tracklet_count > 0
                || hint.profile_downweighted_tracklet_count > 0
                || hint.profile_quarantined_tracklet_count > 0
            {
                SpeakerHintDisposition::PartiallyAccepted
            } else {
                SpeakerHintDisposition::Accepted
            };
            Ok(SpeakerHintEvidenceSummary {
                hint_index: report_count(hint.hint_index, "hint index")?,
                speaker_ref: hint.speaker_ref.clone(),
                policy: hint.policy,
                disposition,
                usable_tracklet_count: report_count(
                    hint.usable_tracklet_count,
                    "usable hint tracklet count",
                )?,
                accepted_tracklet_count: report_count(
                    hint.accepted_tracklet_count,
                    "accepted hint tracklet count",
                )?,
                rejected_tracklet_count: report_count(
                    hint.rejected_tracklet_count,
                    "rejected hint tracklet count",
                )?,
                profile_accepted_tracklet_count: report_count(
                    hint.profile_accepted_tracklet_count,
                    "profile-accepted hint tracklet count",
                )?,
                profile_downweighted_tracklet_count: report_count(
                    hint.profile_downweighted_tracklet_count,
                    "profile-downweighted hint tracklet count",
                )?,
                profile_quarantined_tracklet_count: report_count(
                    hint.profile_quarantined_tracklet_count,
                    "profile-quarantined hint tracklet count",
                )?,
                applied_weight: f64::from(hint.applied_weight),
                contradiction_score: hint.contradiction_score.map(f64::from),
            })
        })
        .collect()
}

fn report_count(value: usize, field: &str) -> FwResult<u64> {
    u64::try_from(value).map_err(|_| {
        FwError::InvalidRequest(format!("{field} exceeds the diarization report schema"))
    })
}

