    #[test]
    fn malformed_acoustic_frames_fail_before_segmentation() {
        let mut wrong_cadence = synthetic_feature(0, 0.0, false, false);
        wrong_cadence.start_ms = 1;
        let error =
            segment_acoustic_frames([wrong_cadence], &AcousticBoundaryHints::default(), || false)
                .expect_err("wrong frame cadence must fail");
        assert!(error.to_string().contains("exact v2 cadence"));

        let mut invalid_pitch = synthetic_feature(0, 0.0, false, false);
        invalid_pitch.voice.f0_hz = Some(-120.0);
        let error =
            segment_acoustic_frames([invalid_pitch], &AcousticBoundaryHints::default(), || false)
                .expect_err("negative pitch must fail");
        assert!(error.to_string().contains("internally consistent"));

        let mut overflowing_distance = synthetic_feature(0, 0.0, false, false);
        overflowing_distance.voice.cepstral_envelope[0] = f32::MAX;
        let error = segment_acoustic_frames(
            [overflowing_distance],
            &AcousticBoundaryHints::default(),
            || false,
        )
        .expect_err("finite values that overflow distance arithmetic must fail");
        assert!(error.to_string().contains("internally consistent"));

        let mut contradictory_quality = synthetic_feature(0, 0.0, false, false);
        contradictory_quality.channel.clipping_fraction = 1.0;
        let error = segment_acoustic_frames(
            [contradictory_quality],
            &AcousticBoundaryHints::default(),
            || false,
        )
        .expect_err("feature values and quality flags must agree");
        assert!(error.to_string().contains("internally consistent"));

        #[cfg(target_pointer_width = "64")]
        {
            let overflowing_index =
                usize::try_from((u64::MAX / 1_000 + 1) / ACOUSTIC_HOP_SAMPLES as u64)
                    .expect("64-bit frame index");
            let mut overflowing = synthetic_feature(0, 0.0, false, false);
            overflowing.frame_index = overflowing_index;
            let error =
                segment_acoustic_frames([overflowing], &AcousticBoundaryHints::default(), || false)
                    .expect_err("timestamp conversion overflow must fail");
            assert!(error.to_string().contains("cadence range"));
        }
    }

    fn profile_tracklet(
        index: usize,
        start_ms: u64,
        end_ms: u64,
        voice: f32,
        channel: f32,
        voiced_frames: usize,
    ) -> AcousticTracklet {
        let frame_count = usize::try_from((end_ms - start_ms) / 10).expect("fixture frame count");
        let valid_voice_frames = voiced_frames.min(frame_count);
        let voice_support = u32::try_from(valid_voice_frames).unwrap_or(u32::MAX);
        AcousticTracklet {
            tracklet_index: index,
            start_ms,
            end_ms,
            frame_count,
            voiced_frame_count: valid_voice_frames,
            identity_frame_count: valid_voice_frames,
            channel_frame_count: frame_count,
            voice_mean: [voice; VOICE_VECTOR_DIMENSIONS],
            voice_variance: [0.01; VOICE_VECTOR_DIMENSIONS],
            voice_valid: [valid_voice_frames > 0; VOICE_VECTOR_DIMENSIONS],
            voice_support: [voice_support; VOICE_VECTOR_DIMENSIONS],
            channel_mean: [channel; CHANNEL_VECTOR_DIMENSIONS],
            channel_variance: [0.01; CHANNEL_VECTOR_DIMENSIONS],
            channel_valid: true,
            channel_dimensions: CHANNEL_VECTOR_DIMENSIONS,
            change_confidence: 0.8,
            overlap_probability: 0.0,
            overlap_suspected: false,
            boundary_evidence: None,
        }
    }

    fn assert_tracklet_feature_bits_eq(expected: &[AcousticTracklet], actual: &[AcousticTracklet]) {
        assert_eq!(expected.len(), actual.len());
        for (expected, actual) in expected.iter().zip(actual) {
            assert_eq!(
                expected.voice_mean.map(f32::to_bits),
                actual.voice_mean.map(f32::to_bits)
            );
            assert_eq!(
                expected.voice_variance.map(f32::to_bits),
                actual.voice_variance.map(f32::to_bits)
            );
            assert_eq!(
                expected.channel_mean.map(f32::to_bits),
                actual.channel_mean.map(f32::to_bits)
            );
            assert_eq!(
                expected.channel_variance.map(f32::to_bits),
                actual.channel_variance.map(f32::to_bits)
            );
            assert_eq!(expected.voice_valid, actual.voice_valid);
            assert_eq!(expected.channel_valid, actual.channel_valid);
            assert_eq!(expected.channel_dimensions, actual.channel_dimensions);
        }
    }

    #[test]
    fn retained_normalization_transform_replays_tracklet_coordinates_bit_exactly() {
        let mut raw = vec![
            profile_tracklet(0, 0, 500, -2.0, -4.0, 50),
            profile_tracklet(1, 500, 1_000, 0.5, 1.0, 50),
            profile_tracklet(2, 1_000, 1_500, 3.0, 5.0, 50),
        ];
        raw[1].voice_mean[7] = 123.0;
        raw[1].voice_variance[7] = 456.0;
        raw[1].voice_valid[7] = false;
        raw[1].voice_support[7] = 0;
        raw[2].channel_valid = false;
        raw[2].channel_frame_count = 0;
        raw[2].channel_dimensions = 0;

        let mut normalized = raw.clone();
        let (summary, transform) = super::normalize_tracklet_features(
            &mut normalized,
            super::AcousticFeatureSchemaVersion::V2,
        )
        .expect("derive and apply normalization");
        assert_eq!(summary.normalized_voice_dimensions, VOICE_VECTOR_DIMENSIONS);
        assert_eq!(
            summary.normalized_channel_dimensions,
            CHANNEL_VECTOR_DIMENSIONS
        );
        assert_eq!(summary.missing_voice_dimensions, 0);
        assert!(transform.voice_valid.iter().all(|valid| *valid));
        assert!(transform.channel_valid.iter().all(|valid| *valid));

        let mut replayed = raw;
        super::apply_acoustic_normalization_transform(
            &mut replayed,
            super::AcousticFeatureSchemaVersion::V2,
            &transform,
        )
        .expect("replay retained normalization");
        assert_tracklet_feature_bits_eq(&normalized, &replayed);
    }

    #[test]
    fn normalization_transform_skips_inactive_zero_scales_and_rejects_active_invalid_scales() {
        let original = vec![profile_tracklet(0, 0, 500, 2.0, -3.0, 50)];
        let mut unchanged = original.clone();
        super::apply_acoustic_normalization_transform(
            &mut unchanged,
            super::AcousticFeatureSchemaVersion::V2,
            &super::AcousticNormalizationTransform::default(),
        )
        .expect("inactive zero scales are not applied");
        assert_tracklet_feature_bits_eq(&original, &unchanged);

        for invalid_scale in [
            0.0,
            -1.0,
            f32::from_bits(1),
            1.0e-22,
            f32::MAX,
            f32::NAN,
            f32::INFINITY,
        ] {
            let mut transform = super::AcousticNormalizationTransform::default();
            transform.voice_valid[0] = true;
            transform.voice_scales[0] = invalid_scale;
            let mut target = original.clone();
            let error = super::apply_acoustic_normalization_transform(
                &mut target,
                super::AcousticFeatureSchemaVersion::V2,
                &transform,
            )
            .expect_err("an active invalid voice scale must fail closed");
            assert!(matches!(error, FwError::ContractViolation(_)));
            assert_tracklet_feature_bits_eq(&original, &target);
        }

        let mut invalid_channel = super::AcousticNormalizationTransform::default();
        invalid_channel.channel_valid[0] = true;
        invalid_channel.channel_scales[0] = 0.0;
        let mut target = original.clone();
        super::apply_acoustic_normalization_transform(
            &mut target,
            super::AcousticFeatureSchemaVersion::V2,
            &invalid_channel,
        )
        .expect_err("an active zero channel scale must fail closed");
        assert_tracklet_feature_bits_eq(&original, &target);

        let mut invalid_center = super::AcousticNormalizationTransform::default();
        invalid_center.voice_valid[0] = true;
        invalid_center.voice_centers[0] = f32::MAX;
        invalid_center.voice_scales[0] = super::MIN_ACOUSTIC_NORMALIZATION_SCALE;
        let mut target = original.clone();
        super::apply_acoustic_normalization_transform(
            &mut target,
            super::AcousticFeatureSchemaVersion::V2,
            &invalid_center,
        )
        .expect_err("an out-of-domain center must fail closed");
        assert_tracklet_feature_bits_eq(&original, &target);

        let mut valid_transform = super::AcousticNormalizationTransform::default();
        for dimension in 0..=1 {
            valid_transform.voice_valid[dimension] = true;
            valid_transform.voice_scales[dimension] = super::MIN_ACOUSTIC_NORMALIZATION_SCALE;
        }
        let mut overflowing_target = original.clone();
        overflowing_target[0].voice_variance[1] = f32::MAX;
        let overflowing_original = overflowing_target.clone();
        super::apply_acoustic_normalization_transform(
            &mut overflowing_target,
            super::AcousticFeatureSchemaVersion::V2,
            &valid_transform,
        )
        .expect_err("a target that would overflow normalization must fail before mutation");
        assert_tracklet_feature_bits_eq(&overflowing_original, &overflowing_target);
    }

    #[test]
    fn normalization_transform_is_schema_bound_and_preserves_inactive_v1_tails() {
        let mut raw_v1 = vec![
            profile_tracklet(0, 0, 500, -2.0, -4.0, 50),
            profile_tracklet(1, 500, 1_000, 3.0, 5.0, 50),
        ];
        for (tracklet_index, tracklet) in raw_v1.iter_mut().enumerate() {
            tracklet.voice_valid[8..].fill(false);
            tracklet.voice_support[8..].fill(0);
            tracklet.channel_dimensions = 8;
            for dimension in 8..VOICE_VECTOR_DIMENSIONS {
                tracklet.voice_mean[dimension] =
                    10_000.0 + tracklet_index as f32 * 100.0 + dimension as f32;
                tracklet.voice_variance[dimension] =
                    f32::from_bits(0x7fc0_0001_u32.wrapping_add(dimension as u32));
            }
            for dimension in 8..CHANNEL_VECTOR_DIMENSIONS {
                tracklet.channel_mean[dimension] =
                    -10_000.0 - tracklet_index as f32 * 100.0 - dimension as f32;
                tracklet.channel_variance[dimension] =
                    f32::from_bits(0x7fc0_0101_u32.wrapping_add(dimension as u32));
            }
        }

        let mut normalized_v1 = raw_v1.clone();
        let (summary, transform) = super::normalize_tracklet_features(
            &mut normalized_v1,
            super::AcousticFeatureSchemaVersion::V1,
        )
        .expect("derive v1 normalization without reading inactive tails");
        assert_eq!(summary.normalized_voice_dimensions, 8);
        assert_eq!(summary.normalized_channel_dimensions, 8);
        assert_eq!(
            summary.missing_voice_dimensions,
            VOICE_VECTOR_DIMENSIONS - 8
        );
        assert!(transform.voice_valid[..8].iter().all(|valid| *valid));
        assert!(transform.voice_valid[8..].iter().all(|valid| !*valid));
        assert!(transform.channel_valid[..8].iter().all(|valid| *valid));
        assert!(transform.channel_valid[8..].iter().all(|valid| !*valid));
        for (raw, normalized) in raw_v1.iter().zip(&normalized_v1) {
            assert_eq!(
                raw.voice_mean[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>(),
                normalized.voice_mean[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>()
            );
            assert_eq!(
                raw.voice_variance[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>(),
                normalized.voice_variance[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>()
            );
            assert_eq!(
                raw.channel_mean[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>(),
                normalized.channel_mean[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>()
            );
            assert_eq!(
                raw.channel_variance[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>(),
                normalized.channel_variance[8..]
                    .iter()
                    .copied()
                    .map(f32::to_bits)
                    .collect::<Vec<_>>()
            );
        }

        let mut replayed_v1 = raw_v1.clone();
        super::apply_acoustic_normalization_transform(
            &mut replayed_v1,
            super::AcousticFeatureSchemaVersion::V1,
            &transform,
        )
        .expect("replay schema-matched v1 normalization");
        assert_tracklet_feature_bits_eq(&normalized_v1, &replayed_v1);

        let mut out_of_prefix_transform = transform;
        out_of_prefix_transform.voice_valid[8] = true;
        out_of_prefix_transform.voice_scales[8] = super::MIN_ACOUSTIC_NORMALIZATION_SCALE;
        let mut out_of_prefix_target = raw_v1.clone();
        super::apply_acoustic_normalization_transform(
            &mut out_of_prefix_target,
            super::AcousticFeatureSchemaVersion::V1,
            &out_of_prefix_transform,
        )
        .expect_err("a v1 transform cannot activate a voice dimension outside its schema");
        assert_tracklet_feature_bits_eq(&raw_v1, &out_of_prefix_target);

        let raw_v2 = vec![profile_tracklet(2, 1_000, 1_500, 1.0, 2.0, 50)];
        let mut voice_mismatched_target = raw_v2.clone();
        voice_mismatched_target[0].channel_dimensions = 8;
        let voice_mismatched_original = voice_mismatched_target.clone();
        super::apply_acoustic_normalization_transform(
            &mut voice_mismatched_target,
            super::AcousticFeatureSchemaVersion::V1,
            &transform,
        )
        .expect_err("a target cannot expose voice dimensions outside declared v1 schema");
        assert_tracklet_feature_bits_eq(&voice_mismatched_original, &voice_mismatched_target);

        let mut normalized_v2 = raw_v2.clone();
        let (_, v2_transform) = super::normalize_tracklet_features(
            &mut normalized_v2,
            super::AcousticFeatureSchemaVersion::V2,
        )
        .expect("derive v2 normalization");

        let mut mismatched_target = raw_v1.clone();
        super::apply_acoustic_normalization_transform(
            &mut mismatched_target,
            super::AcousticFeatureSchemaVersion::V1,
            &v2_transform,
        )
        .expect_err("a v2 transform cannot be applied to declared v1 targets");
        assert_tracklet_feature_bits_eq(&raw_v1, &mismatched_target);

        let mut falsely_declared_target = raw_v1.clone();
        super::apply_acoustic_normalization_transform(
            &mut falsely_declared_target,
            super::AcousticFeatureSchemaVersion::V2,
            &v2_transform,
        )
        .expect_err("v1 channel dimensionality cannot be declared as v2");
        assert_tracklet_feature_bits_eq(&raw_v1, &falsely_declared_target);

        let mut mixed_schema = raw_v2;
        mixed_schema.push(raw_v1[0].clone());
        let mixed_original = mixed_schema.clone();
        super::normalize_tracklet_features(
            &mut mixed_schema,
            super::AcousticFeatureSchemaVersion::V2,
        )
        .expect_err("mixed-schema normalization must fail before derivation or mutation");
        assert_tracklet_feature_bits_eq(&mixed_original, &mixed_schema);
    }

    #[test]
    fn normalization_transform_retained_v1_finish_is_schema_bound_noop() {
        let hints = AcousticBoundaryHints::default();
        let frames = (0..64)
            .map(|index| synthetic_feature(index, 0.1, false, false))
            .collect::<Vec<_>>();
        let mut segmenter = super::AcousticSegmenter::new_with_supervised_boundaries(
            &hints,
            &[],
            super::AcousticFeatureAblation::V1,
            super::AcousticChangeDetectorMode::FixedSafeV1,
        )
        .expect("v1 segmenter");
        for frame in frames.clone() {
            segmenter.push(frame).expect("v1 frame");
        }
        let (tracklets, summary, _, _, transform) = segmenter
            .finish_with_normalization()
            .expect("v1 finish with retained transform");
        assert_eq!(
            transform.feature_schema_version,
            super::AcousticFeatureSchemaVersion::V1
        );
        assert!(transform.voice_valid.iter().all(|valid| !*valid));
        assert!(transform.channel_valid.iter().all(|valid| !*valid));
        assert_eq!(summary.normalized_voice_dimensions, 0);
        assert_eq!(summary.normalized_channel_dimensions, 0);
        assert_eq!(
            summary.missing_voice_dimensions,
            VOICE_VECTOR_DIMENSIONS - 8
        );

        let mut replayed = tracklets.clone();
        super::apply_acoustic_normalization_transform(
            &mut replayed,
            super::AcousticFeatureSchemaVersion::V1,
            &transform,
        )
        .expect("retained v1 no-op transform");
        assert_tracklet_feature_bits_eq(&tracklets, &replayed);

        let public_output = super::segment_acoustic_frames_with_schema(
            frames,
            &hints,
            super::AcousticFeatureSchemaVersion::V1,
            || false,
        )
        .expect("public v1 segmentation");
        assert_eq!(public_output, (tracklets, summary));
    }

    #[test]
    fn normalization_transform_default_finish_discards_only_the_retained_transform() {
        let hints = AcousticBoundaryHints::default();
        let frames = (0..96)
            .map(|index| {
                synthetic_feature(index, if index < 48 { -0.25 } else { 0.25 }, false, false)
            })
            .collect::<Vec<_>>();
        let make_segmenter = || {
            super::AcousticSegmenter::new_with_supervised_boundaries(
                &hints,
                &[],
                super::AcousticFeatureAblation::FullV2,
                super::AcousticChangeDetectorMode::FixedSafeV1,
            )
            .expect("default segmenter")
        };
        let mut default_segmenter = make_segmenter();
        let mut retained_segmenter = make_segmenter();
        for frame in frames.clone() {
            default_segmenter
                .push(frame.clone())
                .expect("default frame");
            retained_segmenter.push(frame).expect("retained frame");
        }

        let default_output = default_segmenter.finish().expect("default finish");
        let (tracklets, summary, change_evidence, sidecar_selector, transform) = retained_segmenter
            .finish_with_normalization()
            .expect("finish with retained normalization");
        assert_eq!(default_output.0, tracklets);
        assert_tracklet_feature_bits_eq(&default_output.0, &tracklets);
        assert_eq!(default_output.1, summary);
        assert_eq!(default_output.2, change_evidence);
        assert_eq!(default_output.3, sidecar_selector);
        assert_eq!(
            transform.voice_valid.iter().filter(|valid| **valid).count(),
            summary.normalized_voice_dimensions
        );
        assert_eq!(
            transform
                .channel_valid
                .iter()
                .filter(|valid| **valid)
                .count(),
            summary.normalized_channel_dimensions
        );

        let public_output =
            segment_acoustic_frames(frames, &hints, || false).expect("public default segmentation");
        assert_eq!(public_output, (tracklets, summary));
    }

    fn sequential_profile_tracklets(
        voices: &[f32],
        duration_ms: u64,
        voiced_frames: usize,
    ) -> Vec<AcousticTracklet> {
        voices
            .iter()
            .copied()
            .enumerate()
            .map(|(index, voice)| {
                let start_ms = u64::try_from(index)
                    .expect("fixture index")
                    .saturating_mul(duration_ms);
                profile_tracklet(
                    index,
                    start_ms,
                    start_ms.saturating_add(duration_ms),
                    voice,
                    0.0,
                    voiced_frames,
                )
            })
            .collect()
    }

    fn ecapa_representation(
        discovery: super::EcapaSpeakerEmbedding,
        validation: Option<super::EcapaSpeakerEmbedding>,
        discovery_weight: f32,
        validation_weight: f32,
    ) -> super::EcapaTrackletRepresentation {
        super::EcapaTrackletRepresentation {
            discovery,
            validation,
            discovery_weight,
            validation_weight,
        }
    }

    fn residual_birth_basis(slot: usize) -> super::EcapaSpeakerEmbedding {
        let mut embedding = [0.0_f32; crate::ecapa_conformance::ECAPA_EMBEDDING_DIMENSIONS];
        embedding[slot * 4..slot * 4 + 4].fill(0.5);
        embedding
    }

    fn residual_birth_cluster(
        members: Vec<usize>,
        neural_voice: super::EcapaSpeakerEmbedding,
    ) -> super::AcousticCluster {
        let weight = members.len() as f32 * 100.0;
        super::AcousticCluster {
            earliest_ms: members.first().copied().unwrap_or_default() as u64 * 1_000,
            prototype_members: members,
            evidence_mode: DiarizationSpeakerEvidenceMode::EcapaOnly,
            neural_voice: Some(neural_voice),
            neural_weight: weight,
            voice: [0.0; VOICE_VECTOR_DIMENSIONS],
            voice_valid: [true; VOICE_VECTOR_DIMENSIONS],
            scale: [0.01; VOICE_VECTOR_DIMENSIONS],
            channel: [0.0; CHANNEL_VECTOR_DIMENSIONS],
            channel_valid: true,
            channel_dimensions: CHANNEL_VECTOR_DIMENSIONS,
            weight,
            sse: 0.0,
            hard_anchor: None,
            label_hint: None,
            reliability: 1.0,
        }
    }

    fn residual_birth_fixture() -> (
        Vec<AcousticTracklet>,
        super::EcapaTrackletEmbeddings,
        Vec<super::AcousticCluster>,
    ) {
        let speaker_a = residual_birth_basis(0);
        let speaker_b = residual_birth_basis(1);
        let speaker_d = residual_birth_basis(2);
        let speakers = [speaker_b, speaker_a, speaker_b, speaker_a, speaker_d];
        let tracklets = (0..speakers.len())
            .map(|index| {
                profile_tracklet(
                    index,
                    index as u64 * 1_000,
                    (index as u64 + 1) * 1_000,
                    index as f32,
                    0.0,
                    100,
                )
            })
            .collect::<Vec<_>>();
        let embeddings = speakers
            .into_iter()
            .enumerate()
            .map(|(index, embedding)| {
                (
                    index,
                    ecapa_representation(embedding, Some(embedding), 100.0, 100.0),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let incumbent = vec![
            residual_birth_cluster(vec![0, 1, 2, 3], speaker_a),
            residual_birth_cluster(vec![4], speaker_d),
        ];
        (tracklets, embeddings, incumbent)
    }

    fn residual_birth_policy(max: usize) -> super::SpeakerCountPolicy {
        super::SpeakerCountPolicy {
            min: 1,
            max,
            exact: None,
        }
    }

    #[test]
    fn residual_birth_accepts_one_cross_fitted_pair_and_conserves_every_member() {
        let (tracklets, embeddings, incumbent) = residual_birth_fixture();
        let untouched = incumbent[1].clone();
        let mut never_cancel = || false;
        let (replacement, evidence) = super::apply_ecapa_residual_birth(
            &incumbent,
            &tracklets,
            &embeddings,
            residual_birth_policy(3),
            5,
            5,
            super::EcapaResidualBirthMode::DevelopmentCandidateV1,
            &"a".repeat(64),
            &mut never_cancel,
        )
        .expect("cross-fitted residual birth");
        let output = replacement.expect("the reciprocal residual pair should create one speaker");
        assert_eq!(
            evidence.proposal_kind,
            Some(super::EcapaResidualBirthProposalKind::ReciprocalPair)
        );
        assert!(evidence.birth_applied);
        assert_eq!(evidence.fallback_reason, None);
        assert_eq!(
            (
                evidence.incumbent_cluster_count,
                evidence.output_cluster_count
            ),
            (2, 3)
        );
        assert_eq!(evidence.resources.candidate_split_count, 1);
        assert_eq!(evidence.resources.committed_birth_count, 1);
        assert_eq!(evidence.resources.lloyd_assignment_visits, 4 * 8);
        assert_eq!(output[0].prototype_members, [0, 2]);
        assert_eq!(output[1].prototype_members, [1, 3]);
        assert_eq!(output[2], untouched);
        let mut members = output
            .iter()
            .flat_map(|cluster| cluster.prototype_members.iter().copied())
            .collect::<Vec<_>>();
        members.sort_unstable();
        assert_eq!(members, [0, 1, 2, 3, 4]);

        let mut never_cancel = || false;
        let (replayed, replay_evidence) = super::apply_ecapa_residual_birth(
            &incumbent,
            &tracklets,
            &embeddings,
            residual_birth_policy(3),
            5,
            5,
            super::EcapaResidualBirthMode::DevelopmentCandidateV1,
            &"a".repeat(64),
            &mut never_cancel,
        )
        .expect("deterministic residual replay");
        assert_eq!(replayed, Some(output));
        assert_eq!(replay_evidence, evidence);
    }

    #[test]
    fn residual_birth_freezes_one_proposal_and_never_promotes_a_valid_runner_up() {
        let (tracklets, mut embeddings, incumbent) = residual_birth_fixture();
        let speaker_a = residual_birth_basis(0);
        for member in [0usize, 2] {
            embeddings
                .get_mut(&member)
                .expect("B observation")
                .validation = Some(speaker_a);
        }
        let mut never_cancel = || false;
        let mut budget = super::EcapaResidualBirthBudget::new(&mut never_cancel).expect("budget");
        let mut resources = super::EcapaResidualBirthResourceSummary::default();
        let frozen = super::discover_residual_birth_proposal(
            &incumbent,
            &tracklets,
            &embeddings,
            &mut budget,
            &mut resources,
        )
        .expect("discovery")
        .expect("frozen proposal");
        assert_eq!((frozen.first_seed, frozen.second_seed), (0, Some(2)));
        assert!(
            !super::validate_frozen_residual_birth_proposal(
                frozen,
                &incumbent,
                &embeddings,
                &mut budget,
                &mut resources,
            )
            .expect("selected validation")
        );
        let runner_up = super::EcapaResidualBirthProposal {
            parent_index: 0,
            kind: super::EcapaResidualBirthProposalKind::ReciprocalPair,
            first_seed: 1,
            second_seed: Some(3),
            discovery_score: frozen.discovery_score,
        };
        assert!(
            super::validate_frozen_residual_birth_proposal(
                runner_up,
                &incumbent,
                &embeddings,
                &mut budget,
                &mut resources,
            )
            .expect("runner-up validation")
        );

        let snapshot = incumbent.clone();
        let mut never_cancel = || false;
        let (replacement, evidence) = super::apply_ecapa_residual_birth(
            &incumbent,
            &tracklets,
            &embeddings,
            residual_birth_policy(3),
            5,
            5,
            super::EcapaResidualBirthMode::DevelopmentCandidateV1,
            &"b".repeat(64),
            &mut never_cancel,
        )
        .expect("held-out rejection");
        assert!(replacement.is_none());
        assert_eq!(incumbent, snapshot);
        assert_eq!(
            evidence.proposal_kind,
            Some(super::EcapaResidualBirthProposalKind::ReciprocalPair)
        );
        assert_eq!(
            evidence.fallback_reason,
            Some(super::EcapaResidualBirthFallbackReason::HeldoutValidationFailed)
        );
        assert_eq!(evidence.resources.candidate_split_count, 0);
        assert_eq!(evidence.resources.committed_birth_count, 0);
        assert_eq!(
            evidence.incumbent_cluster_count,
            evidence.output_cluster_count
        );
    }

    #[test]
    fn residual_birth_caps_ranked_residuals_pairs_and_count_before_work() {
        let speaker = residual_birth_basis(0);
        let tracklets = (0..12)
            .map(|index| {
                profile_tracklet(
                    index,
                    index as u64 * 1_000,
                    (index as u64 + 1) * 1_000,
                    0.0,
                    0.0,
                    100,
                )
            })
            .collect::<Vec<_>>();
        let embeddings = (0..12)
            .map(|index| {
                (
                    index,
                    ecapa_representation(speaker, Some(speaker), 100.0, 100.0),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let incumbent = vec![residual_birth_cluster((0..12).collect(), speaker)];
        let mut never_cancel = || false;
        let mut budget = super::EcapaResidualBirthBudget::new(&mut never_cancel).expect("budget");
        let mut resources = super::EcapaResidualBirthResourceSummary::default();
        let ranked =
            super::ranked_parent_residuals(&incumbent[0], &embeddings, &mut budget, &mut resources)
                .expect("bounded residual ranking");
        assert_eq!(ranked.len(), 8);
        assert_eq!(resources.residual_observation_count, 12);
        assert_eq!(resources.maximum_retained_residual_observations, 8);

        let mut never_cancel = || false;
        let mut budget = super::EcapaResidualBirthBudget::new(&mut never_cancel).expect("budget");
        let mut resources = super::EcapaResidualBirthResourceSummary::default();
        let proposal = super::discover_residual_birth_proposal(
            &incumbent,
            &tracklets,
            &embeddings,
            &mut budget,
            &mut resources,
        )
        .expect("bounded proposal discovery");
        assert!(proposal.is_none());
        assert_eq!(resources.parent_count_scanned, 1);
        assert_eq!(resources.leave_pair_out_pair_count, 28);
        assert_eq!(resources.maximum_retained_residual_observations, 8);

        let mut never_cancel = || false;
        let (replacement, evidence) = super::apply_ecapa_residual_birth(
            &incumbent,
            &tracklets,
            &embeddings,
            residual_birth_policy(1),
            12,
            12,
            super::EcapaResidualBirthMode::DevelopmentCandidateV1,
            &"c".repeat(64),
            &mut never_cancel,
        )
        .expect("count ceiling fallback");
        assert!(replacement.is_none());
        assert_eq!(
            evidence.fallback_reason,
            Some(super::EcapaResidualBirthFallbackReason::CountCeilingReached)
        );
        assert_eq!(
            evidence.resources,
            super::EcapaResidualBirthResourceSummary::default()
        );
    }

    #[test]
    fn residual_birth_polls_at_the_declared_operation_cadence() {
        let speaker = residual_birth_basis(0);
        let tracklets = (0..40)
            .map(|index| {
                profile_tracklet(
                    index,
                    index as u64 * 1_000,
                    (index as u64 + 1) * 1_000,
                    0.0,
                    0.0,
                    100,
                )
            })
            .collect::<Vec<_>>();
        let embeddings = (0..40)
            .map(|index| {
                (
                    index,
                    ecapa_representation(speaker, Some(speaker), 100.0, 100.0),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let incumbent = vec![residual_birth_cluster((0..40).collect(), speaker)];
        let mut polls = 0usize;
        let error = super::apply_ecapa_residual_birth(
            &incumbent,
            &tracklets,
            &embeddings,
            residual_birth_policy(2),
            40,
            40,
            super::EcapaResidualBirthMode::DevelopmentCandidateV1,
            &"d".repeat(64),
            &mut || {
                polls += 1;
                polls == 2
            },
        )
        .expect_err("the second cadence poll cancels residual work");
        assert!(matches!(error, FwError::Cancelled(_)));
        assert_eq!(polls, 2);
    }

