    #[test]
    fn probabilistic_scoring_merges_channel_variants_but_separates_voices() {
        let request = DiarizationRequest::default();
        let same_voice = vec![
            profile_tracklet(0, 0, 500, 0.25, -1.0, 50),
            profile_tracklet(1, 500, 1_000, 0.25, 1.0, 50),
        ];
        let same_enrollment =
            enroll_known_speaker_profiles(&same_voice, &request, 1_000).expect("enrollment");
        let same_result = super::cluster_acoustic_tracklets_with_mode(
            &same_voice,
            &same_enrollment,
            &request.speaker_count,
            512,
            super::AcousticClusteringMode::ProbabilisticV1,
            || false,
        )
        .expect("probabilistic same-speaker clustering");
        assert_eq!(
            same_result.executed_mode,
            super::AcousticClusteringMode::ProbabilisticV1
        );
        assert_eq!(same_result.detected_speakers, 1, "{same_result:#?}");
        assert_eq!(same_result.bootstrap_stability, 1.0);
        assert!(
            same_result
                .merge_trace
                .iter()
                .all(|step| step.channel_distance.is_some()
                    && step.same_speaker_probability.is_some())
        );

        let different_voices = vec![
            profile_tracklet(0, 0, 500, -1.5, 0.0, 50),
            profile_tracklet(1, 500, 1_000, 1.5, 0.0, 50),
            profile_tracklet(2, 1_000, 1_500, -1.5, 0.0, 50),
            profile_tracklet(3, 1_500, 2_000, 1.5, 0.0, 50),
        ];
        let different_enrollment =
            enroll_known_speaker_profiles(&different_voices, &request, 2_000).expect("enrollment");
        let different_result = super::cluster_acoustic_tracklets_with_mode(
            &different_voices,
            &different_enrollment,
            &request.speaker_count,
            512,
            super::AcousticClusteringMode::ProbabilisticV1,
            || false,
        )
        .expect("probabilistic different-speaker clustering");
        assert_eq!(
            different_result.executed_mode,
            super::AcousticClusteringMode::ProbabilisticV1
        );
        assert_eq!(
            different_result.detected_speakers, 2,
            "{different_result:#?}"
        );
    }

    #[test]
    fn probabilistic_count_selection_reverses_many_false_boundaries() {
        let request = DiarizationRequest::default();
        let tracklets = (0..8)
            .map(|index| {
                profile_tracklet(
                    index,
                    index as u64 * 400,
                    index as u64 * 400 + 400,
                    if index.is_multiple_of(2) { 0.20 } else { 0.21 },
                    if index.is_multiple_of(2) { -0.8 } else { 0.8 },
                    40,
                )
            })
            .collect::<Vec<_>>();
        let enrollment =
            enroll_known_speaker_profiles(&tracklets, &request, 3_200).expect("enrollment");
        let (result, count_merge_steps) = super::cluster_acoustic_tracklets_with_mode_internal(
            &tracklets,
            &enrollment,
            &request.speaker_count,
            512,
            super::AcousticClusteringMode::ProbabilisticV1,
            None,
            crate::model::DiarizationSpeakerEvidenceMode::AcousticV2,
            || false,
        )
        .expect("probabilistic clustering");
        assert_eq!(
            result.executed_mode,
            super::AcousticClusteringMode::ProbabilisticV1,
            "{result:#?}"
        );
        assert_eq!(result.detected_speakers, 1, "{result:#?}");
        // Count selection and local attribution abstention are deliberately
        // separate decisions. Alternating channel conditions can leave some
        // tracklets UNKNOWN even when the supported global count is one.
        assert!(
            result
                .assignments
                .iter()
                .any(|assignment| assignment.speaker_ref.is_some()),
            "{result:#?}"
        );
        let resources = &result
            .count_estimate
            .as_ref()
            .expect("count estimate")
            .resources;
        assert_eq!(resources.prototype_count, 8);
        assert_eq!(resources.affinity_pair_evaluations, 56);
        assert!(resources.retained_sparse_edges <= 32, "{resources:#?}");
        assert_eq!(resources.stability_replicates, 5);
        assert!(resources.solver_iterations > 0, "{resources:#?}");
        assert!(
            resources
                .solver_residual
                .is_some_and(|residual| { residual <= super::SPEAKER_COUNT_EIGENSOLVER_TOLERANCE }),
            "{resources:#?}"
        );
        assert_eq!(count_merge_steps.len(), 7, "{result:#?}");
        assert!(count_merge_steps.windows(2).all(|window| {
            window[0].remaining_clusters.checked_sub(1) == Some(window[1].remaining_clusters)
        }));
        assert!(count_merge_steps.iter().all(|step| {
            step.same_speaker_probability.is_finite()
                && (0.0..=1.0).contains(&step.same_speaker_probability)
        }));
    }

    #[test]
    fn fused_merge_risk_count_is_bounded_and_permutation_invariant() {
        let lane = |selected_count, losses: [f64; 3]| super::ProbabilisticLaneResult {
            selected_count,
            groups: vec![vec![0]],
            risk_curve: super::SpeakerCountRiskCurve {
                selected_count,
                points: losses
                    .into_iter()
                    .enumerate()
                    .map(|(index, expected_loss)| super::SpeakerCountRiskPoint {
                        count: index + 1,
                        expected_loss,
                    })
                    .collect(),
            },
            merge_steps: Vec::new(),
            merge_replay: Vec::new(),
        };
        let lanes = vec![
            lane(2, [5.0, 0.0, 3.0]),
            lane(2, [4.0, 0.0, 2.0]),
            lane(2, [6.0, 0.0, 4.0]),
            lane(3, [6.0, 1.0, 0.0]),
            lane(3, [7.0, 1.5, 0.0]),
        ];
        let policy = super::SpeakerCountPolicy {
            min: 1,
            max: 3,
            exact: None,
        };
        assert_eq!(super::fused_merge_risk_count(&lanes, None, policy), Some(2));

        let mut reversed = lanes.clone();
        reversed.reverse();
        assert_eq!(
            super::fused_merge_risk_count(&reversed, None, policy),
            Some(2)
        );

        let exact = super::SpeakerCountPolicy {
            min: 3,
            max: 3,
            exact: Some(3),
        };
        assert_eq!(
            super::fused_merge_risk_count(&lanes, None, exact),
            Some(3),
            "a hard count restricts candidate search without changing lane losses"
        );
    }

    #[test]
    fn fused_merge_risk_excludes_counts_unreachable_in_any_lane() {
        let lane = |selected_count, points: &[(usize, f64)]| super::ProbabilisticLaneResult {
            selected_count,
            groups: vec![vec![0]],
            risk_curve: super::SpeakerCountRiskCurve {
                selected_count,
                points: points
                    .iter()
                    .map(|&(count, expected_loss)| super::SpeakerCountRiskPoint {
                        count,
                        expected_loss,
                    })
                    .collect(),
            },
            merge_steps: Vec::new(),
            merge_replay: Vec::new(),
        };
        let lanes = vec![
            lane(3, &[(2, 3.0), (3, 0.0), (4, 2.0)]),
            lane(3, &[(3, 0.0), (4, 1.0)]),
        ];
        let policy = super::SpeakerCountPolicy {
            min: 2,
            max: 4,
            exact: None,
        };
        let points = super::merge_risk_loss_points(&lanes, policy)
            .expect("the common feasible count domain must remain usable");
        assert_eq!(
            points.iter().map(|(count, _)| *count).collect::<Vec<_>>(),
            vec![3, 4]
        );
        assert_eq!(super::fused_merge_risk_count(&lanes, None, policy), Some(3));
    }

    #[test]
    fn consensus_replays_each_lane_hierarchy_at_the_fused_count() {
        let lane = super::ProbabilisticLaneResult {
            selected_count: 4,
            groups: vec![vec![0], vec![1], vec![2], vec![3]],
            risk_curve: super::SpeakerCountRiskCurve {
                selected_count: 4,
                points: (1..=4)
                    .map(|count| super::SpeakerCountRiskPoint {
                        count,
                        expected_loss: (4 - count) as f64,
                    })
                    .collect(),
            },
            merge_steps: Vec::new(),
            merge_replay: vec![(0, 1), (2, 3), (0, 2)],
        };

        assert_eq!(
            super::probabilistic_lane_groups_at_count(&lane, 4, 2),
            Some(vec![vec![0, 1], vec![2, 3]])
        );
        assert_eq!(
            super::probabilistic_lane_groups_at_count(&lane, 4, 1),
            Some(vec![vec![0, 1, 2, 3]])
        );
        assert_eq!(super::probabilistic_lane_groups_at_count(&lane, 4, 5), None);
    }

    #[test]
    fn diarization_hardening_unselected_channel_pair_cannot_upgrade_consensus_provenance() {
        let mut initial = (0..4)
            .map(|index| residual_birth_cluster(vec![index], residual_birth_basis(0)))
            .collect::<Vec<_>>();
        for cluster in &mut initial {
            cluster.evidence_mode = DiarizationSpeakerEvidenceMode::EcapaWithAcousticChannel;
        }
        for cluster in &mut initial[..2] {
            cluster.channel_valid = false;
            cluster.channel_dimensions = 0;
        }
        assert!(super::cluster_pair_has_usable_channel_evidence(
            &initial[2],
            &initial[3],
            super::SpeakerPairPerturbation::Full,
        ));

        let lane = super::ProbabilisticLaneResult {
            selected_count: 3,
            groups: vec![vec![0, 1], vec![2], vec![3]],
            risk_curve: super::SpeakerCountRiskCurve {
                selected_count: 3,
                points: vec![super::SpeakerCountRiskPoint {
                    count: 3,
                    expected_loss: 0.0,
                }],
            },
            merge_steps: Vec::new(),
            merge_replay: vec![(0, 1)],
        };
        let lanes = vec![lane; super::SPEAKER_COUNT_PERTURBATION_LANES];
        let (clusters, merge_trace, used_channel_evidence) =
            super::coassociation_consensus_clusters(
                &initial,
                &BTreeSet::new(),
                &lanes,
                3,
                &mut || false,
            )
            .expect("consensus clustering")
            .expect("stable selected partition");
        assert_eq!(clusters.len(), 3);
        assert_eq!(merge_trace.len(), 1);
        assert!(
            !used_channel_evidence,
            "an unrelated usable candidate must not upgrade the selected partition"
        );
    }

