    #[test]
    fn fixed_safe_infer_reports_explicit_uncalibrated_count_evidence() {
        let request = DiarizationRequest::default();
        let tracklets = sequential_profile_tracklets(&[0.0; 6], 500, 50);
        let enrollment =
            enroll_known_speaker_profiles(&tracklets, &request, 3_000).expect("enrollment");
        let result =
            cluster_acoustic_tracklets(&tracklets, &enrollment, &request.speaker_count, 64, || {
                false
            })
            .expect("fixed-safe clustering");
        let estimate = result
            .count_estimate
            .as_ref()
            .expect("native count object must never silently disappear");
        estimate.validate().expect("valid count estimate");
        assert_eq!(
            estimate.calibration_status,
            SpeakerCountCalibrationStatus::FixedSafeUncalibrated
        );
        assert_eq!(estimate.selected_count, None);
        assert!(estimate.posterior.is_empty());
        assert_eq!(estimate.unresolved_probability, 1.0);
        assert_eq!(estimate.lanes.len(), 6);

        let outcome =
            super::public_speaker_count_outcome(&request.speaker_count, &result).expect("outcome");
        assert_eq!(outcome.status, SpeakerCountOutcomeStatus::Unresolved);
        assert!(
            outcome
                .reasons
                .contains(&SpeakerCountOutcomeReason::SpeakerCountEvidenceUnresolved),
            "{outcome:#?}"
        );
    }

    #[test]
    fn hard_count_outcome_depends_only_on_supported_count_equality() {
        let request = SpeakerCountRequest::HardConstraint { count: 2 };
        let tracklets = sequential_profile_tracklets(&[0.0, 0.0, 0.0, 4.0, 4.0, 4.0], 500, 50);
        let mut result = cluster_with_hard_count(&tracklets, 2);
        assert_eq!(result.detected_speakers, 2, "{result:#?}");

        // These broad quality gates still control the pipeline fallback status,
        // but they must not rewrite the narrower public count-equality claim.
        result.constraints_satisfied = false;
        result.dominant_speaker_share = 0.99;
        result.speaker_separation_satisfied = false;

        let outcome = super::public_speaker_count_outcome(&request, &result).expect("outcome");
        assert_eq!(outcome.status, SpeakerCountOutcomeStatus::Satisfied);
        assert!(
            outcome
                .reasons
                .contains(&SpeakerCountOutcomeReason::RequestedCountMatched),
            "{outcome:#?}"
        );
        assert!(
            !outcome
                .reasons
                .contains(&SpeakerCountOutcomeReason::RequestedCountMismatch),
            "{outcome:#?}"
        );
        assert!(
            outcome
                .reasons
                .contains(&SpeakerCountOutcomeReason::DominantSpeakerShareExceeded),
            "{outcome:#?}"
        );
        assert!(
            outcome
                .reasons
                .contains(&SpeakerCountOutcomeReason::AmbiguousSpeakerSeparation),
            "{outcome:#?}"
        );
    }

