    #[test]
    fn ecapa_embedding_validation_rejects_corruption_deterministically() {
        let tracklets = sequential_profile_tracklets(&[0.0], 500, 50);
        let mut embedding = [0.0_f32; crate::ecapa_conformance::ECAPA_EMBEDDING_DIMENSIONS];
        embedding[3] = 1.0;
        let valid = ecapa_representation(embedding, None, 50.0, 0.0);

        let mut zero_norm = valid;
        zero_norm.discovery.fill(0.0);
        let mut non_finite = valid;
        non_finite.discovery[7] = f32::NAN;
        let mut non_finite_weight = valid;
        non_finite_weight.discovery_weight = f32::INFINITY;
        let invalid_validation_weight = ecapa_representation(embedding, Some(embedding), 50.0, 0.0);
        let invalid_absent_validation_weight = ecapa_representation(embedding, None, 50.0, 1.0);
        let cases = [
            BTreeMap::from([(0usize, zero_norm)]),
            BTreeMap::from([(0usize, non_finite)]),
            BTreeMap::from([(0usize, non_finite_weight)]),
            BTreeMap::from([(0usize, invalid_validation_weight)]),
            BTreeMap::from([(0usize, invalid_absent_validation_weight)]),
            BTreeMap::from([(99usize, valid)]),
        ];
        for embeddings in cases {
            let first = super::validate_ecapa_tracklet_embeddings(&tracklets, &embeddings)
                .expect_err("corrupt ECAPA evidence must fail closed")
                .to_string();
            let replay = super::validate_ecapa_tracklet_embeddings(&tracklets, &embeddings)
                .expect_err("corrupt ECAPA replay must fail closed")
                .to_string();
            assert_eq!(first, replay);
            assert!(first.contains(
                "ECAPA tracklet embeddings must be finite, non-zero, and reference an existing tracklet"
            ));
        }
    }

    #[test]
    fn ecapa_pair_evidence_separates_identical_and_opposite_embeddings() {
        let mut first = [0.0_f32; crate::ecapa_conformance::ECAPA_EMBEDDING_DIMENSIONS];
        first[3] = 1.0;
        let opposite = first.map(|value| -value);
        let channel = [0.0_f32; super::CHANNEL_VECTOR_DIMENSIONS];
        let same = super::ecapa_speaker_pair_evidence(
            &first,
            50.0,
            &channel,
            false,
            0,
            &first,
            50.0,
            &channel,
            false,
            0,
            super::SpeakerPairPerturbation::Full,
            crate::model::DiarizationSpeakerEvidenceMode::EcapaOnly,
        )
        .expect("same evidence");
        let different = super::ecapa_speaker_pair_evidence(
            &first,
            50.0,
            &channel,
            false,
            0,
            &opposite,
            50.0,
            &channel,
            false,
            0,
            super::SpeakerPairPerturbation::Full,
            crate::model::DiarizationSpeakerEvidenceMode::EcapaOnly,
        )
        .expect("different evidence");
        assert!(same.same_speaker_probability > 0.95, "{same:?}");
        assert!(different.same_speaker_probability < 0.01, "{different:?}");
        let calibration = super::acoustic_speaker_pair_calibration();
        let merge_threshold = calibration.false_merge_loss
            / (calibration.false_merge_loss + calibration.false_split_loss);
        let distance = super::ECAPA_DIFFERENT_SPEAKER_COSINE_DISTANCE_OPERATING_POINT;
        let different_log_odds = super::ECAPA_PAIR_DIFFERENT_LOGIT_INTERCEPT
            + super::ECAPA_PAIR_COSINE_DISTANCE_WEIGHT * distance;
        let same_probability = super::logistic_probability(-different_log_odds);
        assert!((same_probability - merge_threshold).abs() < 1.0e-6);
        assert_eq!(
            super::ECAPA_ROBUST_SEPARATION_COSINE_DISTANCE,
            super::ECAPA_DIFFERENT_SPEAKER_COSINE_DISTANCE_OPERATING_POINT
        );
        let robust_log_odds = super::ECAPA_PAIR_DIFFERENT_LOGIT_INTERCEPT
            + super::ECAPA_PAIR_COSINE_DISTANCE_WEIGHT
                * super::ECAPA_ROBUST_SEPARATION_COSINE_DISTANCE;
        let robust_same_probability = super::logistic_probability(-robust_log_odds);
        assert!(
            robust_same_probability <= merge_threshold + 1.0e-6,
            "the final separation gate must not certify a pair that the declared loss model would merge"
        );
        let below_gate_same_probability = super::logistic_probability(
            -(super::ECAPA_PAIR_DIFFERENT_LOGIT_INTERCEPT
                + super::ECAPA_PAIR_COSINE_DISTANCE_WEIGHT
                    * (super::ECAPA_ROBUST_SEPARATION_COSINE_DISTANCE - 0.10)),
        );
        assert!(below_gate_same_probability > merge_threshold);
        assert_eq!(super::ecapa_segment_evidence_weight(0.0), 0.25);
        assert_eq!(super::ecapa_segment_evidence_weight(50.0), 1.0);
        assert_eq!(super::ecapa_segment_evidence_weight(1_000.0), 4.0);
        let ecapa_only_sha256 = super::ecapa_speaker_pair_calibration_sha256(
            crate::model::DiarizationSpeakerEvidenceMode::EcapaOnly,
        );
        let fused_sha256 = super::ecapa_speaker_pair_calibration_sha256(
            crate::model::DiarizationSpeakerEvidenceMode::EcapaWithAcousticChannel,
        );
        assert_eq!(ecapa_only_sha256.len(), 64);
        assert!(
            ecapa_only_sha256
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit())
        );
        assert_ne!(ecapa_only_sha256, fused_sha256);
    }

